-- GENERATED by `npm run seed:sql` from src/core/categories.ts and src/data/seed-scenarios.ts.
-- Do not edit by hand. Seed scenarios are hand-written and pre-approved.

insert into public.categories (id, name, description, icon, color, active, sort_order) values
  ('data-privacy', 'Data Privacy', 'Collecting, sharing and protecting personal information.', 'lock-closed', '#38BDF8', true, 0),
  ('cybersecurity', 'Cybersecurity', 'Hacking, vulnerabilities, passwords and responsible security practice.', 'shield-checkmark', '#2DD4BF', true, 1),
  ('intellectual-property', 'Intellectual Property', 'Copyright, licensing, piracy and giving credit.', 'bulb', '#FBBF24', true, 2),
  ('digital-citizenship', 'Digital Citizenship', 'Respectful, responsible and safe behaviour online.', 'people', '#A78BFA', true, 3),
  ('ai-ethics', 'Artificial Intelligence Ethics', 'Bias, transparency and accountability in AI systems.', 'hardware-chip', '#F472B6', true, 4),
  ('academic-integrity', 'Academic Integrity', 'Honesty in schoolwork, exams and research.', 'school', '#60A5FA', true, 5),
  ('social-media', 'Social Media Ethics', 'Sharing, misinformation, consent and online reputation.', 'chatbubbles', '#FB923C', true, 6),
  ('professional-ethics', 'Professional Ethics', 'Duties of IT professionals to employers, clients and the public.', 'briefcase', '#34D399', true, 7),
  ('software-development', 'Software Development Ethics', 'Quality, honesty and harm prevention when building software.', 'code-slash', '#22D3EE', true, 8),
  ('accessibility', 'Digital Accessibility', 'Designing technology that everyone can use.', 'accessibility', '#C084FC', true, 9),
  ('environmental', 'Environmental Ethics', 'E-waste, energy use and sustainable computing.', 'leaf', '#4ADE80', true, 10),
  ('digital-rights', 'Digital Rights', 'Free expression, surveillance and access to technology.', 'globe', '#F87171', true, 11)
on conflict (id) do update set name = excluded.name, description = excluded.description, icon = excluded.icon,
  color = excluded.color, active = excluded.active, sort_order = excluded.sort_order;

insert into public.scenarios (id, category_id, scenario_text, correct_answer, explanation, ethical_principles,
  recommended_action, difficulty_score, difficulty_reasoning, learning_objective, generation_source, approval_status) values
  (md5('seed-dp-01')::uuid, 'data-privacy', 'A student saw a classmate type their password and later logs into the classmate''s account to read their private messages.', 'unethical', 'Using someone else''s credentials without permission is unauthorised access and a clear invasion of their privacy, no matter how the password was learned.', array['Privacy', 'Consent', 'Respect for autonomy']::text[], 'Never use another person''s credentials. Let the classmate know their password may have been seen so they can change it.', 1, 'A direct, recognisable privacy violation with no competing responsibilities.', 'Recognise that knowing a password is not the same as having permission to use it.', 'seed', 'approved'),
  (md5('seed-dp-02')::uuid, 'data-privacy', 'Before posting a group photo from a class event, a student asks everyone in it whether they are comfortable with it being shared online.', 'ethical', 'Asking for consent before sharing images of people respects their control over their own personal information and online presence.', array['Consent', 'Privacy']::text[], null, 2, 'A simple, positive example of consent in everyday social sharing.', 'Understand that photos of people are personal data that deserve consent before sharing.', 'seed', 'approved'),
  (md5('seed-dp-03')::uuid, 'data-privacy', 'A fitness app shares users'' precise location history with advertisers and only mentions it deep inside a long privacy policy.', 'unethical', 'Burying sensitive data sharing in fine print does not produce meaningful informed consent. Location history can reveal homes, routines and habits, so users should clearly understand and agree to its use.', array['Informed consent', 'Transparency', 'Privacy']::text[], 'Explain data sharing in plain language at the moment it matters and let users opt in, not opt out.', 4, 'Requires recognising that technically disclosed practices can still be unethical.', 'Distinguish legal disclosure from genuinely informed consent.', 'seed', 'approved'),
  (md5('seed-dp-04')::uuid, 'data-privacy', 'A school IT administrator securely deletes old student records that are no longer needed, following the school''s data retention policy.', 'ethical', 'Keeping personal data only as long as it is needed (data minimisation) reduces the harm a breach could cause and respects the people the data describes.', array['Data minimisation', 'Privacy', 'Responsibility']::text[], null, 5, 'Deleting data might feel risky, so players must reason about minimisation as a privacy principle.', 'Learn that deleting unneeded personal data can be an ethical, protective act.', 'seed', 'approved'),
  (md5('seed-dp-05')::uuid, 'data-privacy', 'A hospital data analyst is asked by a worried friend to check whether a mutual acquaintance was admitted last week. The analyst has system access.', 'unethical', 'Access to confidential records is granted for job duties only. Looking someone up for personal reasons breaches patient confidentiality, even with good intentions.', array['Confidentiality', 'Privacy', 'Authorised access only']::text[], 'Decline politely and explain that you can only access records for work purposes.', 6, 'The kind motive and legitimate access create tension that must be reasoned through.', 'Understand that legitimate access rights do not cover personal curiosity or favours.', 'seed', 'approved'),
  (md5('seed-dp-06')::uuid, 'data-privacy', 'A company "anonymises" a customer dataset by removing names only, then publishes it for researchers even though birth dates and postcodes remain.', 'unethical', 'Combinations like birth date and postcode can re-identify many individuals. Releasing such data exposes people to privacy harm while claiming it is anonymous.', array['Privacy', 'Avoid harm', 'Honesty']::text[], 'Use proper de-identification techniques, assess re-identification risk and share data under agreements that limit misuse.', 8, 'Requires technical knowledge of re-identification and a benefit-to-research trade-off.', 'Learn that removing names alone does not make data anonymous.', 'seed', 'approved'),
  (md5('seed-dp-07')::uuid, 'data-privacy', 'A company gets an informal request from police for a user''s data with no warrant. It asks for the proper legal order before sharing anything.', 'ethical', 'Requiring due legal process protects users'' privacy rights while still allowing lawful cooperation. Sharing personal data on an informal request would bypass important safeguards.', array['Privacy', 'Rule of law', 'Accountability']::text[], null, 7, 'Involves competing obligations to authorities and to users.', 'Understand how organisations balance legal cooperation with protecting user data.', 'seed', 'approved'),
  (md5('seed-cs-01')::uuid, 'cybersecurity', 'A student guesses a teacher''s weak password and logs into the online gradebook "just to look around".', 'unethical', 'Accessing a system without authorisation is wrong even if nothing is changed. It breaks trust and is illegal in many countries.', array['Authorised access only', 'Respect for property', 'Trust']::text[], 'Never log into accounts that are not yours. If you notice a weak password, tell the person or IT staff.', 1, 'An obvious unauthorised-access case.', 'Recognise that "just looking" is still unauthorised access.', 'seed', 'approved'),
  (md5('seed-cs-02')::uuid, 'cybersecurity', 'An employee gets an email asking them to "verify" their password through a link, so they report it to the IT security team instead of clicking.', 'ethical', 'Reporting suspected phishing protects the employee and colleagues who may receive the same message, supporting the organisation''s security.', array['Security responsibility', 'Avoid harm']::text[], null, 2, 'A familiar, clearly positive security behaviour.', 'Recognise phishing and know that reporting it is the responsible action.', 'seed', 'approved'),
  (md5('seed-cs-03')::uuid, 'cybersecurity', 'A developer stores customers'' passwords in plain text because adding hashing would delay the launch by a day.', 'unethical', 'Plain-text passwords put every customer at serious risk if the database leaks. A one-day delay is small compared to the foreseeable harm.', array['Avoid harm', 'Professional competence', 'Security by design']::text[], 'Hash passwords with a modern, salted algorithm before launch, even if it means a short delay.', 4, 'Requires basic technical knowledge and weighing deadlines against user safety.', 'Understand basic security duties that developers owe to users.', 'seed', 'approved'),
  (md5('seed-cs-04')::uuid, 'cybersecurity', 'A penetration tester, hired under a signed contract defining the scope, exploits a vulnerability on the client''s test server and reports it in detail.', 'ethical', 'Security testing is ethical when it is authorised, stays within the agreed scope and its findings are reported so the client can fix them.', array['Authorisation', 'Honesty', 'Professional responsibility']::text[], null, 5, 'Players must recognise that the same technical act can be ethical when authorised.', 'Distinguish authorised security testing from hacking.', 'seed', 'approved'),
  (md5('seed-cs-05')::uuid, 'cybersecurity', 'A researcher finds a flaw in a popular banking app and immediately posts working exploit code online without telling the bank.', 'unethical', 'Publishing an exploit before the vendor can fix it exposes millions of users to attackers. Responsible disclosure gives the vendor a reasonable chance to patch first.', array['Avoid harm', 'Responsible disclosure', 'Public good']::text[], 'Report the flaw privately to the bank, allow a reasonable fix window, then disclose publicly.', 7, 'Discovering flaws is valuable, so players must weigh transparency against foreseeable harm.', 'Learn the principles of coordinated vulnerability disclosure.', 'seed', 'approved'),
  (md5('seed-cs-06')::uuid, 'cybersecurity', 'An engineer finds a serious flaw. Management refuses to fix it before release despite foreseeable harm. After exhausting internal escalation, the engineer reports it to the relevant regulator.', 'ethical', 'Professional codes such as the ACM Code ask computing professionals to put the public good first and to report risks. When internal channels fail and harm is foreseeable, carefully escalating to an appropriate authority is a responsible step.', array['Public good', 'Avoid harm', 'Professional responsibility']::text[], 'Document the risk, use every internal channel first, then report to an appropriate authority, sharing only what is necessary.', 10, 'Competing loyalties to the employer and the public, with real personal consequences.', 'Understand when and how whistleblowing can be the ethical choice.', 'seed', 'approved'),
  (md5('seed-ip-01')::uuid, 'intellectual-property', 'A student downloads a paid video game from a piracy website because they don''t want to pay for it.', 'unethical', 'Pirating paid software takes the creators'' work without permission or payment and violates copyright.', array['Respect for intellectual property', 'Fairness']::text[], 'Buy the game, wait for a sale, or look for free and legal alternatives.', 1, 'A straightforward copyright violation.', 'Recognise software piracy as taking someone else''s work.', 'seed', 'approved'),
  (md5('seed-ip-02')::uuid, 'intellectual-property', 'A designer uses icons released under a Creative Commons Attribution licence in an app and credits the creator as the licence requires.', 'ethical', 'Open licences grant permission on conditions. Following the attribution requirement respects the creator and the licence terms.', array['Respect for intellectual property', 'Giving credit']::text[], null, 3, 'Requires basic awareness of how open licences work.', 'Understand that open licences come with conditions that must be followed.', 'seed', 'approved'),
  (md5('seed-ip-03')::uuid, 'intellectual-property', 'A teacher shows a short clip from a film in class to analyse its camera work, following the school''s copyright guidance.', 'ethical', 'Using a short excerpt for teaching and analysis, within the institution''s copyright rules, respects creators while supporting education.', array['Respect for intellectual property', 'Education']::text[], null, 3, 'Players must recognise that not every use of copyrighted work is infringement.', 'Learn that limited educational use of works can be legitimate within copyright rules.', 'seed', 'approved'),
  (md5('seed-ip-04')::uuid, 'intellectual-property', 'A developer leaves their job and copies the former employer''s private source code to reuse at a competing company.', 'unethical', 'Proprietary code belongs to the employer. Taking it breaks confidentiality obligations and misappropriates someone else''s property.', array['Respect for intellectual property', 'Confidentiality', 'Honesty']::text[], 'Leave employer code behind and rebuild solutions from your own general knowledge and skills.', 4, 'Some may think code they wrote belongs to them, which requires reasoning about ownership.', 'Distinguish your own skills from your employer''s property.', 'seed', 'approved'),
  (md5('seed-ip-05')::uuid, 'intellectual-property', 'A company uses a GPL-licensed library inside its commercial product and distributes it without releasing the source code the licence requires.', 'unethical', 'Open-source licences are legally binding permissions. Using GPL code commercially is allowed, but only if its conditions, such as sharing source code, are met.', array['Respect for licences', 'Honesty', 'Fairness to contributors']::text[], 'Comply with the licence terms or choose a library whose licence fits the product.', 5, 'Requires knowledge of licence obligations rather than just "free vs paid".', 'Understand that "open source" does not mean "no rules".', 'seed', 'approved'),
  (md5('seed-ip-06')::uuid, 'intellectual-property', 'A startup trains an image generator on artists'' portfolios scraped against a site''s terms, then markets it as able to copy those artists by name.', 'unethical', 'Ignoring a site''s terms to collect creative work and then selling imitations of named artists exploits their work and identity without consent or compensation.', array['Respect for creators', 'Consent', 'Fairness']::text[], 'Use properly licensed or consented training data and do not market imitation of specific living artists.', 8, 'Combines emerging technology, unclear law and several stakeholders.', 'Reason about consent and fairness in AI training data.', 'seed', 'approved'),
  (md5('seed-dc-01')::uuid, 'digital-citizenship', 'A student posts an edited, embarrassing photo of a classmate in a group chat so others will laugh at them.', 'unethical', 'Deliberately humiliating someone online is cyberbullying and can cause lasting emotional harm.', array['Respect', 'Avoid harm', 'Kindness']::text[], 'Do not share content meant to mock someone. Support the person and report bullying if you see it.', 1, 'Clear, intentional harm to another person.', 'Recognise cyberbullying and its impact.', 'seed', 'approved'),
  (md5('seed-dc-02')::uuid, 'digital-citizenship', 'Before reposting a shocking news story, a student checks two reliable sources to make sure it is true.', 'ethical', 'Verifying information before sharing it helps stop misinformation and shows responsibility to others online.', array['Honesty', 'Responsibility']::text[], null, 2, 'A simple, positive information-literacy habit.', 'Build the habit of verifying before sharing.', 'seed', 'approved'),
  (md5('seed-dc-03')::uuid, 'digital-citizenship', 'A gamer uses the in-game reporting tool to report a player who keeps sending hateful slurs in voice chat.', 'ethical', 'Reporting abuse through official tools helps protect others and keeps online communities safe and respectful.', array['Respect', 'Community responsibility']::text[], null, 3, 'Some players may hesitate to report, so it requires light reasoning.', 'Know that reporting harmful behaviour is responsible, not "snitching".', 'seed', 'approved'),
  (md5('seed-dc-04')::uuid, 'digital-citizenship', 'After a minor disagreement, a user creates several fake accounts to flood a small business''s page with negative reviews.', 'unethical', 'Fake reviews deceive other customers and can unfairly damage someone''s livelihood.', array['Honesty', 'Fairness', 'Avoid harm']::text[], 'Leave one honest review from your real account describing your actual experience.', 4, 'Requires seeing beyond the user''s grievance to the deception involved.', 'Understand how deceptive online behaviour harms real people.', 'seed', 'approved'),
  (md5('seed-dc-05')::uuid, 'digital-citizenship', 'A user realises a rumour they shared was false, so they post a correction and apologise to the person it was about.', 'ethical', 'Correcting misinformation you spread and apologising takes responsibility for the harm and helps repair it.', array['Honesty', 'Accountability']::text[], null, 4, 'Players must recognise corrective action as ethical even though the original act was not.', 'Learn that owning mistakes online is part of good digital citizenship.', 'seed', 'approved'),
  (md5('seed-dc-06')::uuid, 'digital-citizenship', 'A popular streamer shares a critic''s username and tells followers to "let them know how you feel". Thousands of hostile messages follow.', 'unethical', 'Directing a large audience at one person predictably leads to harassment. The streamer bears responsibility for the harm they encouraged even without sending a message themselves.', array['Avoid harm', 'Responsibility for influence', 'Respect']::text[], 'Respond to criticism directly and calmly, and never point an audience at an individual.', 6, 'Harm is indirect and the streamer never personally insults anyone.', 'Understand indirect responsibility for harassment.', 'seed', 'approved'),
  (md5('seed-ai-01')::uuid, 'ai-ethics', 'A company uses an AI chatbot for customer support but tells customers they are chatting with a human employee named "Sarah".', 'unethical', 'People have a right to know when they are interacting with AI. Pretending a bot is human is deceptive and undermines trust.', array['Transparency', 'Honesty']::text[], 'Clearly label the chatbot as AI and offer a way to reach a human.', 2, 'A recognisable deception with little competing context.', 'Understand the importance of AI transparency.', 'seed', 'approved'),
  (md5('seed-ai-02')::uuid, 'ai-ethics', 'A team building a face-recognition feature tests its accuracy across different skin tones, ages and genders before release.', 'ethical', 'Testing for unequal performance helps catch bias before it harms people, supporting fairness and non-discrimination.', array['Fairness', 'Non-discrimination', 'Avoid harm']::text[], null, 3, 'Requires awareness that AI systems can perform unequally across groups.', 'Learn that bias testing is a core part of responsible AI.', 'seed', 'approved'),
  (md5('seed-ai-03')::uuid, 'ai-ethics', 'A hospital uses an AI tool to flag possible problems in X-rays, but a qualified doctor reviews every result before any diagnosis.', 'ethical', 'Keeping a qualified human in the loop combines AI assistance with professional accountability for decisions that affect health.', array['Human oversight', 'Accountability', 'Avoid harm']::text[], null, 5, 'Players must reason about how AI can be used responsibly, not just whether it is used.', 'Understand human oversight in high-stakes AI.', 'seed', 'approved'),
  (md5('seed-ai-04')::uuid, 'ai-ethics', 'A bank uses an AI model that rejects loan applications without any explanation, and staff are told never to override it.', 'unethical', 'High-impact decisions need explanations and a way to challenge errors. Removing human review leaves people unable to understand or contest decisions about them.', array['Accountability', 'Explainability', 'Fairness']::text[], 'Provide understandable reasons for decisions and allow human review and appeals.', 6, 'Requires reasoning about due process and automated decision-making.', 'Understand accountability and explainability in automated decisions.', 'seed', 'approved'),
  (md5('seed-ai-05')::uuid, 'ai-ethics', 'A recruiter keeps using a hiring AI after discovering it scores applicants from women''s colleges lower, because hiring has become faster.', 'unethical', 'Knowingly using a discriminatory tool causes unfair harm to applicants. Efficiency does not justify discrimination.', array['Non-discrimination', 'Fairness', 'Accountability']::text[], 'Stop using the tool for decisions, report the bias, and fix or replace it.', 7, 'Involves a real business benefit set against a fairness harm.', 'Recognise when efficiency gains conflict with fairness.', 'seed', 'approved'),
  (md5('seed-ai-06')::uuid, 'ai-ethics', 'Days before an election, a developer posts an unlabelled AI voice clone of a politician saying things they never said, calling it "satire".', 'unethical', 'Unlabelled synthetic media of real people can mislead voters and damage reputations. Calling it satire does not help if viewers cannot tell it is fake.', array['Honesty', 'Avoid harm', 'Democratic integrity']::text[], 'Clearly label synthetic content, and avoid realistic fakes of real people in sensitive contexts.', 8, 'Free expression and satire must be weighed against deception and public harm.', 'Understand the risks of deepfakes and the importance of labelling.', 'seed', 'approved'),
  (md5('seed-ai-07')::uuid, 'ai-ethics', 'A moderation AI wrongly removes posts in a minority language far more often. Leaders leave it unchanged to save money while publicly calling it "fair for everyone".', 'unethical', 'Knowingly allowing unequal harm to one language community, while making misleading public claims, combines discrimination with dishonesty.', array['Fairness', 'Honesty', 'Accountability']::text[], 'Disclose the known limitation, invest in fixing it, and add human review for affected languages.', 9, 'Several principles and stakeholders, with subtle, systemic harm.', 'Reason about systemic bias, cost pressure and honest communication.', 'seed', 'approved'),
  (md5('seed-ac-01')::uuid, 'academic-integrity', 'A student copies a classmate''s homework answers word for word and submits them as their own.', 'unethical', 'Submitting someone else''s work as your own is plagiarism. It is unfair to others and skips the learning the task was meant to build.', array['Honesty', 'Fairness']::text[], 'Do your own work and ask the teacher or classmates for help understanding the material.', 1, 'A clear and familiar violation.', 'Recognise plagiarism in its simplest form.', 'seed', 'approved'),
  (md5('seed-ac-02')::uuid, 'academic-integrity', 'A student puts quotation marks around a sentence taken from an online article and cites the source in their essay.', 'ethical', 'Quoting and citing correctly gives credit to the original author and is honest about which ideas are yours.', array['Honesty', 'Giving credit']::text[], null, 2, 'A simple example of correct academic practice.', 'Know how proper quotation and citation work.', 'seed', 'approved'),
  (md5('seed-ac-03')::uuid, 'academic-integrity', 'A student submits an essay written entirely by an AI chatbot as their own work, even though the assignment forbids AI use.', 'unethical', 'Presenting AI-generated work as your own breaks the assignment rules and misrepresents what you learned.', array['Honesty', 'Following agreed rules']::text[], 'Write the essay yourself. If AI help is unclear, ask the teacher what is allowed.', 3, 'A new technology, but the rule is explicit and the deception is clear.', 'Apply academic integrity to AI tools.', 'seed', 'approved'),
  (md5('seed-ac-04')::uuid, 'academic-integrity', 'Where the teacher allows AI for studying, a student uses an AI tool to explain a hard concept, then writes the assignment in their own words.', 'ethical', 'Using AI as a permitted study aid while producing your own work respects the rules and supports genuine learning.', array['Honesty', 'Responsible use of tools']::text[], null, 4, 'Requires recognising that AI use is not automatically cheating.', 'Distinguish permitted AI assistance from misconduct.', 'seed', 'approved'),
  (md5('seed-ac-05')::uuid, 'academic-integrity', 'A student reuses large parts of an essay they wrote for another class and submits it again without telling either teacher.', 'unethical', 'Resubmitting previous work without permission misrepresents it as new effort for this assignment. Many institutions treat it as self-plagiarism.', array['Honesty', 'Transparency']::text[], 'Ask the teacher whether building on earlier work is allowed and disclose it.', 6, 'It is their own writing, which makes the violation less obvious.', 'Understand self-plagiarism.', 'seed', 'approved'),
  (md5('seed-ac-06')::uuid, 'academic-integrity', 'A research assistant quietly deletes a few results that weaken their professor''s hypothesis, without recording why, to help the paper get published.', 'unethical', 'Removing data without a documented, justified reason is falsification. It misleads other researchers and damages trust in science.', array['Honesty', 'Research integrity', 'Accountability']::text[], 'Report all results, and document and justify any exclusions using pre-agreed criteria.', 8, 'Involves power dynamics and the pretext of legitimate data cleaning.', 'Recognise data manipulation as research misconduct.', 'seed', 'approved'),
  (md5('seed-sm-01')::uuid, 'social-media', 'A student publicly posts a screenshot of a friend''s private message to embarrass them.', 'unethical', 'Sharing private messages without permission breaks trust and the friend''s reasonable expectation of privacy.', array['Privacy', 'Trust', 'Respect']::text[], 'Keep private conversations private. If something worries you, talk to the friend directly.', 1, 'A clear breach of trust.', 'Respect the privacy of personal conversations.', 'seed', 'approved'),
  (md5('seed-sm-02')::uuid, 'social-media', 'A user shares a stranger''s viral video along with the person''s home address so people can "pay them a visit".', 'unethical', 'Publishing someone''s home address (doxxing) exposes them to harassment and physical danger.', array['Avoid harm', 'Privacy', 'Safety']::text[], 'Never share personal details like addresses. Report doxxing when you see it.', 2, 'An obvious safety risk to a real person.', 'Understand doxxing and its dangers.', 'seed', 'approved'),
  (md5('seed-sm-03')::uuid, 'social-media', 'An influencer clearly labels a post with #ad because a brand paid for it.', 'ethical', 'Disclosing paid promotions lets followers judge the content fairly and is honest about conflicts of interest.', array['Honesty', 'Transparency']::text[], null, 3, 'Requires awareness of advertising disclosure.', 'Know why sponsored content must be disclosed.', 'seed', 'approved'),
  (md5('seed-sm-04')::uuid, 'social-media', 'A small business owner removes a glowing review after learning it was secretly written by one of their own employees.', 'ethical', 'Removing a fake review keeps the reviews honest for customers, even though it costs the business a positive rating.', array['Honesty', 'Fairness to customers']::text[], null, 5, 'The action goes against the owner''s interest, so players must look past the outcome.', 'Value honesty even when it is against self-interest.', 'seed', 'approved'),
  (md5('seed-sm-05')::uuid, 'social-media', 'Before publishing protest footage, a journalist blurs the faces of bystanders who were not part of the story.', 'ethical', 'Protecting uninvolved people from unwanted exposure balances public interest reporting with individual privacy and safety.', array['Privacy', 'Avoid harm', 'Responsible journalism']::text[], null, 6, 'Competing values of public information and privacy.', 'Balance newsworthiness against bystanders'' privacy.', 'seed', 'approved'),
  (md5('seed-sm-06')::uuid, 'social-media', 'Engineers tune a feed to promote outrage-inducing posts because it keeps users scrolling, despite internal research showing harm to teenagers.', 'unethical', 'Knowingly designing for engagement that harms vulnerable users puts profit over well-being, against the duty to avoid harm.', array['Avoid harm', 'Public good', 'Responsibility']::text[], 'Raise the research internally and design ranking that weighs user well-being, not just engagement.', 7, 'Harm is systemic and indirect, and business metrics compete with well-being.', 'Reason about the ethics of engagement-driven design.', 'seed', 'approved'),
  (md5('seed-pe-01')::uuid, 'professional-ethics', 'An IT technician repairing a customer''s laptop secretly copies the customer''s personal photos to a USB drive.', 'unethical', 'Technicians are trusted with access to customers'' devices for repairs only. Copying personal files is a serious breach of privacy and trust.', array['Confidentiality', 'Trust', 'Privacy']::text[], 'Access only what the repair requires and never copy customer data.', 1, 'A clear abuse of professional access.', 'Understand the trust placed in IT professionals.', 'seed', 'approved'),
  (md5('seed-pe-02')::uuid, 'professional-ethics', 'A software tester marks failing tests as "passed" so the team can meet its release deadline.', 'unethical', 'Falsifying test results hides real problems from decision-makers and users, who may be harmed by the defects.', array['Honesty', 'Avoid harm', 'Quality']::text[], 'Report failures honestly and let the team decide how to handle the deadline.', 3, 'Deadline pressure creates a mild temptation.', 'Value honest reporting over short-term convenience.', 'seed', 'approved'),
  (md5('seed-pe-03')::uuid, 'professional-ethics', 'A consultant turns down a project because they lack the skills to deliver it safely and recommends a better-qualified colleague.', 'ethical', 'The ACM Code asks professionals to work only within their competence. Declining protects the client from poor or unsafe work.', array['Professional competence', 'Honesty', 'Avoid harm']::text[], null, 4, 'Turning down work may seem unprofessional, so players must reason about competence.', 'Recognise that knowing your limits is professional.', 'seed', 'approved'),
  (md5('seed-pe-04')::uuid, 'professional-ethics', 'An engineer tells their manager they own shares in a vendor bidding for a contract and steps back from evaluating the bids.', 'ethical', 'Disclosing a conflict of interest and stepping back keeps the decision fair and maintains trust.', array['Integrity', 'Transparency', 'Fairness']::text[], null, 5, 'Requires understanding why a personal interest matters even when no wrongdoing has occurred.', 'Understand conflicts of interest and how to handle them.', 'seed', 'approved'),
  (md5('seed-pe-05')::uuid, 'professional-ethics', 'A contractor bills a client for 40 hours of work but actually worked 25, reasoning that the result is just as good as promised.', 'unethical', 'Billing for hours not worked is dishonest, even if the outcome is good. Clients rely on accurate invoices.', array['Honesty', 'Integrity', 'Fairness']::text[], 'Bill accurately. If the agreed price was a fixed fee, use that model openly instead.', 6, 'The good result can make the dishonesty seem harmless.', 'Recognise that good results do not justify dishonest billing.', 'seed', 'approved'),
  (md5('seed-pe-06')::uuid, 'professional-ethics', 'An engineer''s manager orders them to sign off on safety software they know has not been tested. They refuse and put their concerns in writing.', 'ethical', 'Professionals must not approve work they know could endanger people. Refusing and documenting concerns protects the public, even at personal cost.', array['Public safety', 'Integrity', 'Accountability']::text[], null, 8, 'Career pressure and authority compete with public safety.', 'Understand the duty to refuse unsafe approvals.', 'seed', 'approved'),
  (md5('seed-sd-01')::uuid, 'software-development', 'A developer adds hidden code that records users'' keystrokes and sends them to a server "to improve the product".', 'unethical', 'Secretly capturing keystrokes can collect passwords and private messages. Hidden data collection betrays users'' trust and privacy.', array['Privacy', 'Transparency', 'Consent']::text[], 'Collect only necessary, clearly disclosed analytics with user consent.', 2, 'A clear covert privacy violation.', 'Recognise covert data collection as unethical.', 'seed', 'approved'),
  (md5('seed-sd-02')::uuid, 'software-development', 'A developer writes clear documentation and tests so others can safely maintain their code after they leave the team.', 'ethical', 'Maintainable, well-documented code reduces future bugs and helps colleagues, reflecting professional responsibility for quality.', array['Quality', 'Responsibility to colleagues']::text[], null, 2, 'A simple positive practice.', 'See good engineering practice as an ethical responsibility.', 'seed', 'approved'),
  (md5('seed-sd-03')::uuid, 'software-development', 'After launch, a team finds a bug that exposed some users'' email addresses. They fix it, notify affected users and explain what happened.', 'ethical', 'Being transparent about a data exposure lets affected users protect themselves and maintains trust.', array['Transparency', 'Accountability', 'Avoid harm']::text[], null, 4, 'Admitting a mistake can seem bad for business, so players must reason about transparency.', 'Understand responsible incident response.', 'seed', 'approved'),
  (md5('seed-sd-04')::uuid, 'software-development', 'A developer deploys code on Friday that they know has a data-loss bug, hoping nobody notices before Monday, and tells no one.', 'unethical', 'Knowingly releasing a harmful defect and hiding it puts users'' data at risk and prevents the team from responding.', array['Avoid harm', 'Honesty', 'Quality']::text[], 'Delay the release or tell the team about the bug so it can be handled safely.', 4, 'A clear harm, but it requires understanding developer responsibility.', 'Recognise concealment of known defects as unethical.', 'seed', 'approved'),
  (md5('seed-sd-05')::uuid, 'software-development', 'A team designs a subscription that starts with one tap but can only be cancelled by phone during office hours.', 'unethical', 'Making cancellation deliberately harder than sign-up is a manipulative "dark pattern" that exploits users.', array['Respect for autonomy', 'Fairness', 'Honesty']::text[], 'Make cancelling as easy as signing up.', 5, 'Each step looks legal, so players must see the manipulative design.', 'Recognise dark patterns in interface design.', 'seed', 'approved'),
  (md5('seed-sd-06')::uuid, 'software-development', 'A developer refuses a request to secretly slow down older phones to push upgrades, and proposes telling users openly about any performance changes.', 'ethical', 'Declining to build deceptive features and suggesting transparency protects users and respects their ability to make informed choices.', array['Honesty', 'Respect for users', 'Integrity']::text[], null, 7, 'Conflict between employer requests and user interests.', 'Understand a developer''s right and duty to refuse deceptive work.', 'seed', 'approved'),
  (md5('seed-sd-07')::uuid, 'software-development', 'An open-source maintainer finds a hidden backdoor in a release. They pull the release, publish an advisory and warn other projects, though it hurts the project''s reputation.', 'ethical', 'Quickly disclosing a supply-chain compromise lets everyone who depends on the code protect themselves. Public safety outweighs reputation.', array['Avoid harm', 'Transparency', 'Public good']::text[], null, 9, 'Requires technical understanding, many stakeholders and a reputational cost.', 'Understand responsible response to software supply-chain attacks.', 'seed', 'approved'),
  (md5('seed-ax-01')::uuid, 'accessibility', 'A web developer adds descriptive alt text to images so that screen-reader users can understand them.', 'ethical', 'Alt text makes visual content available to blind and low-vision users, supporting equal access.', array['Accessibility', 'Inclusion']::text[], null, 1, 'A simple, clearly inclusive action.', 'Know a basic accessibility practice.', 'seed', 'approved'),
  (md5('seed-ax-02')::uuid, 'accessibility', 'A school launches a video-only course with no captions and tells deaf students to "ask a friend" for help.', 'unethical', 'Leaving out captions excludes deaf and hard-of-hearing students from equal education.', array['Accessibility', 'Fairness', 'Inclusion']::text[], 'Provide captions and transcripts for all video content.', 2, 'Obvious exclusion of a group of learners.', 'Recognise exclusion caused by inaccessible content.', 'seed', 'approved'),
  (md5('seed-ax-03')::uuid, 'accessibility', 'A designer checks that all text in an app has enough colour contrast for people with low vision.', 'ethical', 'Good contrast helps people with low vision and makes the app easier for everyone to read.', array['Accessibility', 'Inclusive design']::text[], null, 3, 'Requires some awareness of accessibility guidelines.', 'Learn colour contrast as an accessibility practice.', 'seed', 'approved'),
  (md5('seed-ax-04')::uuid, 'accessibility', 'A team ships a sign-up form that only works with a mouse, knowing keyboard-only users cannot complete it, and plans to "fix it someday".', 'unethical', 'Knowingly releasing an inaccessible core feature excludes people with motor disabilities and those using assistive technology.', array['Accessibility', 'Fairness', 'Avoid harm']::text[], 'Fix keyboard support before release; accessibility is a requirement, not an extra.', 5, 'Deadline trade-offs make the exclusion seem temporary or minor.', 'Treat accessibility as a release requirement.', 'seed', 'approved'),
  (md5('seed-ax-05')::uuid, 'accessibility', 'A government agency makes an essential benefits application online-only, with no accessible format or alternative for people who cannot use the website.', 'unethical', 'Essential public services must be usable by everyone. Removing alternatives can deny disabled and digitally excluded people support they are entitled to.', array['Accessibility', 'Equal access', 'Public responsibility']::text[], 'Make the service accessible and keep alternative channels such as phone or in-person help.', 7, 'Digitisation is beneficial, so players must reason about who is left behind.', 'Understand the digital divide in public services.', 'seed', 'approved'),
  (md5('seed-en-01')::uuid, 'environmental', 'A student takes an old laptop to a certified e-waste recycling centre instead of throwing it in the bin.', 'ethical', 'Electronics contain toxic and valuable materials. Proper recycling prevents pollution and recovers resources.', array['Environmental responsibility', 'Sustainability']::text[], null, 1, 'A simple, clearly positive action.', 'Know how to dispose of electronics responsibly.', 'seed', 'approved'),
  (md5('seed-en-02')::uuid, 'environmental', 'A company dumps broken computers in a landfill to avoid paying recycling fees.', 'unethical', 'Toxic materials from e-waste can leak into soil and water, harming communities and the environment.', array['Environmental responsibility', 'Avoid harm']::text[], 'Use certified e-waste recycling services.', 2, 'Clear environmental harm for cost savings.', 'Recognise the environmental harm of e-waste.', 'seed', 'approved'),
  (md5('seed-en-03')::uuid, 'environmental', 'A developer optimises a data-heavy app so it uses less energy and data, extending users'' battery life.', 'ethical', 'Efficient software reduces energy use and costs for users and contributes to more sustainable computing.', array['Sustainability', 'Quality']::text[], null, 4, 'Requires connecting software efficiency to environmental impact.', 'See efficiency as an environmental consideration.', 'seed', 'approved'),
  (md5('seed-en-04')::uuid, 'environmental', 'A phone maker glues in batteries so they can''t be replaced, mainly to push customers to buy new phones sooner.', 'unethical', 'Deliberately shortening product life (planned obsolescence) increases e-waste and costs for consumers.', array['Sustainability', 'Fairness to consumers', 'Honesty']::text[], 'Design for repairability and offer battery replacement.', 6, 'Design choices can have legitimate reasons, so players must judge intent and impact.', 'Understand planned obsolescence.', 'seed', 'approved'),
  (md5('seed-en-05')::uuid, 'environmental', 'A company advertises its data centre as "100% green" while its own audit shows most power comes from coal, offset only by cheap, unverified credits.', 'unethical', 'Misleading environmental claims ("greenwashing") deceive customers and hide real environmental impact.', array['Honesty', 'Environmental responsibility', 'Transparency']::text[], 'Report actual energy sources honestly and invest in verified renewable power.', 8, 'Requires understanding carbon offsets and the gap between marketing and reality.', 'Recognise greenwashing.', 'seed', 'approved'),
  (md5('seed-dr-01')::uuid, 'digital-rights', 'A public library offers free computers and Wi-Fi so people without home internet can apply for jobs.', 'ethical', 'Providing access to technology helps close the digital divide and supports equal opportunity.', array['Equal access', 'Inclusion']::text[], null, 1, 'A clearly positive public service.', 'Understand internet access as an opportunity issue.', 'seed', 'approved'),
  (md5('seed-dr-02')::uuid, 'digital-rights', 'A school secretly monitors students'' personal social media accounts outside school hours, with no policy or notice.', 'unethical', 'Covert surveillance of private activity without notice or a clear policy violates students'' privacy and autonomy.', array['Privacy', 'Transparency', 'Proportionality']::text[], 'Have a transparent, limited policy focused on genuine safety concerns.', 4, 'The institution may claim safety motives, requiring reasoning about proportionality.', 'Recognise disproportionate surveillance.', 'seed', 'approved'),
  (md5('seed-dr-03')::uuid, 'digital-rights', 'A messaging app uses end-to-end encryption so that even the company cannot read users'' messages.', 'ethical', 'Strong encryption protects people''s private communications from criminals and misuse, supporting privacy and free expression.', array['Privacy', 'Security', 'Freedom of expression']::text[], null, 5, 'Encryption debates can make this seem controversial.', 'Understand encryption as a protector of rights.', 'seed', 'approved'),
  (md5('seed-dr-04')::uuid, 'digital-rights', 'An internet provider secretly slows down a competitor''s video service while keeping its own video service fast.', 'unethical', 'Secretly discriminating against competitors'' traffic harms fair competition and users'' freedom to choose services.', array['Fairness', 'Transparency', 'Open access']::text[], 'Treat traffic fairly and disclose any network management practices.', 6, 'Requires knowledge of how internet providers can shape traffic.', 'Understand net neutrality.', 'seed', 'approved'),
  (md5('seed-dr-05')::uuid, 'digital-rights', 'A tech company quietly agrees to build a tool that identifies anonymous, peaceful protesters from social media photos, in exchange for a large government contract.', 'unethical', 'Helping to identify peaceful protesters threatens freedom of expression and assembly and can expose people to serious harm.', array['Human rights', 'Avoid harm', 'Freedom of expression']::text[], 'Decline the contract and assess human-rights risks before building surveillance tools.', 9, 'Involves government authority, large commercial incentives and human-rights impacts.', 'Reason about technology''s role in protecting or undermining rights.', 'seed', 'approved')
on conflict (id) do nothing;
